import{z as A,x as B,o as e,c as d,q as i,j as s,D as E,d as t,s as n,S as o,b as r}from"./chunks/framework.C8m1ZpeB.js";const b=JSON.parse('{"title":"Signal 双棘轮","description":"","frontmatter":{"title":"Signal 双棘轮","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/double-ratchet.md","filePath":"cs/double-ratchet.md","lastUpdated":1791413859000}'),p={name:"cs/double-ratchet.md"};function D(h,a,c,m,C,u){const l=B("Mermaid");return e(),d("div",null,[a[2]||(a[2]=i('<h1 id="signal-双棘轮" tabindex="-1">Signal 双棘轮 <a class="header-anchor" href="#signal-双棘轮" aria-label="Permalink to &quot;Signal 双棘轮&quot;">​</a></h1><div class="epigraph"><p>DH 棘轮换根，对称棘轮用 KDF 推下一条链密钥：每条消息一把键，过去的键删掉。前向保密变成消息粒度，延迟乱序用跳过的键缓存来收。</p><footer>—— Perrin and Marlinspike, The Double Ratchet Algorithm；对照 Krawczyk 的 KDF 提取</footer></div><p>上一课<a href="/cs/forward-secrecy">前向保密</a>停在「每个会话一把临时 DH」。缺口是<strong>长时间对话</strong>：消息很多、可乱序、可延迟。双棘轮把 PFS 推到消息级，并引入后向保密（泄漏后未来仍能自愈）的工程直觉。</p><p>后课默认已经读完本课钉下的合同，只补差，不从该领域第一性原理重开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>TLS 会话相对短。即时通讯里同一对端持续数年。每条消息都做完整握手太贵。双棘轮：收到新 DH 公钥就进一格 DH 棘轮；同格内用 HKDF 推链。缺口是状态机，不是再定义 ECDH。</p><h3 id="不是区块链" tabindex="-1">不是区块链 <a class="header-anchor" href="#不是区块链" aria-label="Permalink to &quot;不是区块链&quot;">​</a></h3><p>棘轮是密钥演化，不需要全局账本。不要把本课写成加密货币。</p><p><span class="marginnote">Signal 协议规格公开。本课不写客户端取证步骤。跳过的消息键要限时缓存，否则乱序无法解密。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>画 DH 棘轮与对称棘轮两条轴。指出会话建立仍要身份（X3DH 只点名）。丢失消息：保留若干跳过键。对照 TLS：记录层序号 vs 消息链。</p>',11)),(e(),s(o,null,{default:E(()=>[n(l,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20DH%5B%22DH%20%E6%A3%98%E8%BD%AE%E6%8D%A2%E6%A0%B9%22%5D%20--%3E%20CK%5B%22%E9%93%BE%E5%AF%86%E9%92%A5%22%5D%0A%20%20CK%20--%3E%20MK%5B%22%E6%B6%88%E6%81%AF%E9%94%AE%22%5D%0A%20%20MK%20--%3E%20DEL%5B%22%E7%94%A8%E5%90%8E%E5%88%A0%E9%99%A4%22%5D%0A%20%20CK%20--%3E%20CK2%5B%22HKDF%20%E6%8E%A8%E4%B8%8B%E4%B8%80%E9%93%BE%E9%94%AE%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=r("h2",{id:"机制",tabindex:"-1"},[t("机制 "),r("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=r("p",null,"消息键短命，服务前向：旧密文在键删后不可解。新 DH 进格服务后向：当前链泄漏后，下一格根与之独立。身份仍依赖长期身份钥与预密钥包——那是PKI/信任启动，不是棘轮算术。",-1)),(e(),s(o,null,{default:E(()=>[n(l,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20LR%0A%20%20subgraph%20AX1%5B%22DH%20%E6%A3%98%E8%BD%AE%EF%BC%9A%E6%94%B6%E5%88%B0%E6%96%B0%E5%85%AC%E9%92%A5%E6%89%8D%E8%BF%9B%E4%B8%80%E6%A0%BC%22%5D%0A%20%20%20%20R0%5B%22%E6%A0%B9%20v0%22%5D%20--%3E%7C%22%E5%AF%B9%E6%96%B9%E6%96%B0%20DH%20%E5%85%AC%E9%92%A5%22%7C%20R1%5B%22%E6%A0%B9%20v1%22%5D%0A%20%20%20%20R1%20--%3E%7C%22%E5%86%8D%E6%8D%A2%20DH%22%7C%20R2%5B%22%E6%A0%B9%20v2%22%5D%0A%20%20end%0A%20%20R0%20--%3E%7C%22HKDF%20%E6%8E%A8%E9%93%BE%22%7C%20C0A%5B%22%E9%93%BE%E9%94%AE%20%E2%86%92%20%E6%B6%88%E6%81%AF%E9%94%AE%20M1%20%E2%86%92%20%E5%88%A0%E9%99%A4%22%5D%0A%20%20C0A%20--%3E%20C0B%5B%22%E6%B6%88%E6%81%AF%E9%94%AE%20M2%20%E2%86%92%20%E5%88%A0%E9%99%A4%22%5D%0A%20%20R1%20--%3E%7C%22HKDF%20%E6%8E%A8%E9%93%BE%22%7C%20C1A%5B%22%E6%96%B0%E9%93%BE%E9%94%AE%EF%BC%9A%E4%B8%8E%20v0%20%E7%8B%AC%E7%AB%8B%22%5D%0A%20%20C0B%20--%3E%20SKIP%5B%22%E4%B9%B1%E5%BA%8F%E5%88%B0%E8%BE%BE%E7%9A%84%E6%97%A7%E6%B6%88%E6%81%AF%EF%BC%9A%E7%94%A8%E8%B7%B3%E8%BF%87%E9%94%AE%E7%BC%93%E5%AD%98%E8%A7%A3%E5%BC%80%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=i('<p><span class="marginnote">术语翻译：「棘轮」就是那种只能单向扳动、扳不回去的机械齿条。这里指密钥只能用 KDF 一步步往前推——推过去的旧密钥被删掉后，即使攻击者拿到当前状态，也算不出任何一条已经用过的消息键，倒不回历史。</span></p><p><span class="marginnote">数字实例：跳过键缓存是这么用的——对方连发第 1 到第 10 条消息，你只收到第 3 条。协议必须为第 1、2 条各算一个消息键暂存（缓存通常设上限，比如 1000 个、并带过期时间），等对方补传到达时才能解。上限是防御：无限缓存会被「蒸发消息」撑爆内存。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把 X3DH 的全部代数写完。后量子下一课：KEM 替换 DH 格时，棘轮形状仍在，困难问题换成格上封装。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li><p>会话级 PFS 不够长对话；棘轮到消息键。</p></li><li><p>DH 换根 + HKDF 链；用后删键。</p></li><li><p>乱序靠有限跳过缓存，不是无限保留。 <span class="marginnote">常见误区：前向保密和后向保密方向相反。前向：今天的密钥被偷，偷不到<strong>过去</strong>的消息（旧键已删）。后向：今天的密钥被偷，等下一次 DH 换格后，<strong>未来</strong>的密钥与小偷手里的状态无关，自动自愈。双棘轮的两个方向各管一头。</span></p></li><li><p>下一课：后量子 Kyber/Dilithium 换困难问题。</p></li><li><p>出处：Perrin and Marlinspike, Double Ratchet；RFC 5869；对照 TLS 1.3。</p></li></ul>',6))])}const f=A(p,[["render",D]]);export{b as __pageData,f as default};
